#!/usr/bin/env bash
# Populate py-sandbox/vendor/ with every runtime dependency on a single module path:
#   1. prebuilt wasm32-wasi packages copied from wasi-deps/ (the binary deps)
#   2. pure-python packages from vendor-requirements.txt (binaries stripped so the
#      prebuilt wasm packages always win and no macOS .so sneaks into the component)
#
# build.sh runs this when vendor/ is missing or when vendor-requirements.txt or this
# script changes. vendor/ is git-ignored and fully regenerated by this script.
# Requires Python 3.12 (python3.12 on PATH, or PYTHON=/path/to/python3.12).
set -euo pipefail

HERE="$(cd "$(dirname "${BASH_SOURCE[0]}")" && pwd)"
# Prebuilt wasm32-wasi packages are committed in wasi-deps/ (see its README for
# provenance and licenses). SPIN_PYTHON_DEPS overrides the location.
DEPS="${SPIN_PYTHON_DEPS:-$HERE/wasi-deps}"
VENDOR="$HERE/vendor"
PY="${PYTHON:-python3.12}"

# pip resolves the pure-python deps for the running interpreter, so it must match the
# CPython 3.12 that componentize-py embeds and the cpython-312 prebuilt packages.
py_ver="$("$PY" -c 'import sys; print("%d.%d" % sys.version_info[:2])' 2>/dev/null || true)"
if [ "$py_ver" != "3.12" ]; then
  echo "ERROR: vendor/ must be built with Python 3.12, but $PY is ${py_ver:-not a runnable Python}." >&2
  echo "       Set PYTHON=/path/to/python3.12 (build.sh does this with its venv)." >&2
  exit 1
fi

# Prebuilt wasm32-wasi packages (cpython-312-wasm32-wasi .so + sources).
PREBUILT=(_yaml charset_normalizer frozenlist multidict numpy pydantic_core \
          regex sqlalchemy tiktoken tiktoken_ext wrapt yaml yarl)

echo ">> resetting $VENDOR"
rm -rf "$VENDOR"
mkdir -p "$VENDOR"

echo ">> copying prebuilt wasm packages from $DEPS"
missing=()
for pkg in "${PREBUILT[@]}"; do
  if [ -e "$DEPS/$pkg" ]; then
    cp -R "$DEPS/$pkg" "$VENDOR/$pkg"
  else
    echo "   ERROR: prebuilt package '$pkg' not found in $DEPS" >&2
    missing+=("$pkg")
  fi
done
# Fail hard: these are required binary deps. A missing one silently produces a broken
# component (e.g. numpy/pydantic_core absent) that would otherwise build and publish green.
if [ "${#missing[@]}" -gt 0 ]; then
  echo "ERROR: ${#missing[@]} required prebuilt package(s) missing from $DEPS: ${missing[*]}" >&2
  echo "       Restore py-sandbox/wasi-deps, or point SPIN_PYTHON_DEPS at a complete copy." >&2
  exit 1
fi

echo ">> installing pure-python deps into a temp dir"
TMP="$(mktemp -d)"
trap 'rm -rf "$TMP"' EXIT
"$PY" -m pip install --quiet --target "$TMP" -r "$HERE/vendor-requirements.txt"

echo ">> merging pure-python deps into vendor (prebuilt wins; binaries stripped)"
shopt -s nullglob
# Package dirs and their .dist-info metadata (some packages read importlib.metadata.version).
for entry in "$TMP"/*/; do
  name="$(basename "$entry")"
  case "$name" in
    __pycache__|bin) continue ;;
  esac
  if [ -e "$VENDOR/$name" ]; then
    echo "   keep prebuilt: $name"
    continue
  fi
  cp -R "$entry" "$VENDOR/$name"
  # Drop macOS/linux binaries from pip; the wasm32-wasi .so come from the prebuilt set,
  # and these pure-python packages have working pure fallbacks (e.g. markupsafe._native).
  find "$VENDOR/$name" \( -name '*.so' -o -name '*.pyd' -o -name '*.dylib' \) -delete
  find "$VENDOR/$name" -name '__pycache__' -type d -prune -exec rm -rf {} +
done
# top-level single-file modules (e.g. typing_extensions.py)
for f in "$TMP"/*.py; do
  cp "$f" "$VENDOR/"
done

echo ">> vendor/ contents:"
ls -1 "$VENDOR"
echo ">> done. total size: $(du -sh "$VENDOR" | cut -f1)"
